content.query:
let interactions = union isfuzzy=true
    (datatable(TimeGenerated: datetime, InteractionId: string, SessionId: string, RequestId: string, InteractionType: string, AppClass: string, UserPrincipalName: string, BodyContent: string, BodyTruncated: bool, CollectorRunId: string)[]),
    (M365GovCopilotInteractionContent_CL)
    | where TimeGenerated {TimeRange}
    | summarize arg_max(TimeGenerated, *) by InteractionId;
let userFilter = '{UserFilter:escape}';
let searchText = '{SearchText:escape}';
let idFilter = '{SessionFilter:escape}';
interactions
| where isempty(userFilter) or UserPrincipalName contains userFilter
| where isempty(searchText) or BodyContent has searchText
| where isempty(idFilter) or SessionId == idFilter or InteractionId == idFilter or RequestId == idFilter
| project TimeGenerated, UserPrincipalName, InteractionType, AppClass, BodyContent, BodyTruncated, SessionId, RequestId, InteractionId
| order by TimeGenerated desc
| take 500
